import json
r=json.load(open('scenery/route.json'))
def show(o,d=0,k=''):
    pad='  '*d
    if isinstance(o,dict):
        print(pad+k+'{'+str(len(o))+' keys}')
        for kk,v in list(o.items())[:30]: show(v,d+1,kk+': ')
    elif isinstance(o,list):
        print(pad+k+'[list len %d]'%len(o) + (' first='+json.dumps(o[0])[:200] if o else ''))
    else:
        print(pad+k+json.dumps(o)[:200])
show(r)
"; echo ===; cat scenery/validation.json | head -80

