227	  /* ---------- step ---------- */
228	
229	  function step(ctx, dt) {
230	    const st = ctx.state, T = ctx.T;
231	    if (!(dt > 0) || st.paused) return;
232	    if (st.mode === 'countdown') {
233	      st.countdown -= dt;
234	      if (st.countdown <= 0) {
235	        st.countdown = 0;
236	        st.mode = 'running';
237	        st.purl.action = 'run';
238	        st.loop.action = 'run';
239	        ctx.emit({ type: 'go' });
240	      }
241	      return;
242	    }
243	    if (st.mode === 'running') {
244	      if (tutorialHold(ctx)) {
245	        // First lesson: the race clock and both racers' progress stand still; only the stitch moves.
246	        sim.stitches.update(ctx, dt);
247	        tutorialHold(ctx);
248	        updateProgress(ctx);
249	        return;
250	      }
251	      st.time += dt;
252	      expire(ctx);
253	      sim.stitches.update(ctx, dt);
254	      const spans = updatePurl(ctx, dt);
255	      sim.snagling.update(ctx, dt, spans);
256	      sim.loopAI.update(ctx, dt);
257	      settleFinish(ctx);
258	      tutorialHold(ctx);                 // report the lesson from the step Purl arrives in
259	      const p = st.purl;
260	      if (p.failAt !== null && st.mode === 'running' && st.time >= p.failAt - 1e-9) {
261	        st.mode = 'failed';
262	        p.action = 'failed';
263	        p.speed = 0;
264	        ctx.emit({ type: 'fail' });
265	      }
266	    } else if (st.mode === 'finished') {
267	      const racing = st.result && st.result.loopStillRacing;
268	      if (racing) st.time += dt;
269	      expire(ctx);
270	      coastPurl(ctx, dt);
271	      if (racing) sim.loopAI.update(ctx, dt);
272	      settleFinish(ctx);
273	    } else if (st.mode === 'failed') {
274	      return;
275	    }
276	    if (st.gate.state === 'opening') {
277	      st.gate.t = Math.min(1, st.gate.t + dt / T.gateOpenTime);
278	      if (st.gate.t >= 1) st.gate.state = 'open';
279	    }
280	    updateProgress(ctx);
281	  }
