324	    for (let i = 0; i < seg.stops.length; i++) {
325	      const stop = seg.stops[i];
326	      if (stop.f >= f - 1e-9 && ctx.state.stitches[stop.stitch] && !sim.stitches.passable(ctx, stop.stitch)) {
327	        if (b === null || stop.f < b) b = stop.f;
