401	  function refreshObjective(ctx) {
402	    const st = ctx.state, p = st.purl, seg = ctx.route[p.seg];
403	    if (p.finishTime !== null) { st.objective = ctx.level.completeObjective || seg.def.objectiveDone || st.objective; return; }
404	    if (seg.kind !== 'plate') return;
405	    const def = seg.def;
406	    let obj = def.objective || st.objective;
407	    const sid = Object.keys(st.stitches || {}).filter(function (k) { return st.stitches[k].segIndex === seg.index; })[0];
