521	  function coastPurl(ctx, dt) {
522	    const p = ctx.state.purl, T = ctx.T;
523	    stepJump(ctx, p, dt);
524	    stepLane(ctx, p, dt);
525	    p.speed = U.approach(p.speed, 0, T.purlAccel * dt);
526	    if (p.speed <= 0) return;
527	    const res = walk(ctx.route, p, p.speed * dt, function () { return null; }, null);
528	    p.distance += p.speed * dt - res.leftover;
529	    if (res.blocked) p.speed = 0;
530	  }
