550	  /* ---------- input ---------- */
551	
552	  function input(ctx, ev) {
553	    const st = ctx.state, p = st.purl, T = ctx.T;
554	    if (!ev || st.paused || st.mode !== 'running') return;
555	    if (ev.type === 'tap') {
556	      st.stats.taps += 1;
557	      sim.stitches.tap(ctx, ev.target);
558	      return;
559	    }
560	    if (ev.type === 'pull') {
561	      // A grip can only start once Purl stands at that stitch's stop (he must be in reach of the loop).
562	      if (ev.phase === 'start' && p.waitingFor !== ev.target) return;
563	      if (sim.stitches.pull(ctx, ev.target, ev.phase, +ev.amount || 0)) {
564	        if (ev.phase === 'start') st.stats.pulls = (st.stats.pulls || 0) + 1;
565	        tutorialHold(ctx);
566	      }
567	      return;
568	    }
569	    if (ev.type !== 'swipe' || p.finishTime !== null || p.failAt !== null) return;
570	    if (st.tutorial) return;             // standing at the first lesson: no jumps or lane changes (they would freeze)
571	    if (ev.dir === 'left' || ev.dir === 'right') {
572	      const special = st.transition && st.transition.kind !== 'connector';
573	      const spacing = special ? T.connectorLaneSpacing : laneSpacing(ctx, ctx.route[p.seg], p.f);
574	      if (spacing < T.laneMinSpacing) return;
575	      const lane = U.clamp(p.lane + (ev.dir === 'left' ? -1 : 1), -1, 1);
576	      if (lane !== p.lane) { p.lane = lane; ctx.emit({ type: 'lane', who: 'purl', lane: lane }); }
577	    } else if (ev.dir === 'up') {
578	      if (st.time < p.tangledUntil) return;
579	      if (!p.airborne) startJump(ctx, p);
580	      else if (T.jumpTime - p.jumpT <= T.inputBufferTime) p.jumpBuffered = true;
581	    }
582	  }
