        const s = spans[i];
        if (s.seg !== it.segIndex || !hitF(it.f, s, T.pickupRadiusF)) continue;
        if (it.status === 'uncollected') { collect(ctx, it); break; }
        if (it.status === 'dropped' && Math.abs(p.laneX - it.lane) < T.dropPickupLane) {
