  function loopPickups(ctx, spans) {
    const T = ctx.T;
    ownItems(ctx.state, 'loop').forEach(function (it) {
      if (it.status !== 'uncollected' || !it.available) return;
      for (let i = 0; i < spans.length; i++) {
