+  assert.equal(st.mode, 'countdown'); assert.equal(st.time, 0);
+  assert.deepEqual(st.purl.pos, p0); assert.deepEqual(st.loop.pos, l0);
+  const ev = stepFor(race, 0.2);
+  assert.equal(st.mode, 'running');
