+  assert.ok(t >= 0.18 && t <= 0.27, 'stopped in ' + t.toFixed(3) + ' s');
+  assert.ok(Math.abs((st.purl.mainS - s0) - v0 * T.brakeTime / 2) < 0.1, 'braking distance');
+  assert.equal(st.purl.action, 'stopped');
