+  }
+});
+
+test('pause freezes everything; a paused-and-resumed race replays identically', () => {
+  const WW = load();
+  const a = newRace(WW, 7), b = newRace(WW, 7);
+  go(a); go(b);
+  stepFor(a, 4); stepFor(b, 4);
