+  race.debug.teleport('purl', b.startS - 8, -1.6);
+  stepUntil(race, (s) => s.purl.branchLock !== null || s.purl.road !== 'main', 5);
+  for (let i = 0; i < 4; i++) race.input({ type: 'steer', direction: 1 });
+  stepUntil(race, (s) => s.purl.road !== 'main', 3);
+  stepFor(race, 1);
+  for (let i = 0; i < 4; i++) race.input({ type: 'steer', direction: 1 });
