  /* ---------- pattern functions (u, v in 0..1 of one tile) ---------- */

  function flower(u, v, cx, cy, r, petals, petal, centre, ring) {
    const dx = u - cx, dy = v - cy;
    const d = Math.hypot(dx, dy) / r;
