+      const nmap = tex(normalMap(pair.height, o.bump || 2.2), o.repeat, false);
+      const m = new THREE.MeshStandardMaterial({
+        map: map, normalMap: nmap, roughness: o.roughness == null ? 0.92 : o.roughness, metalness: 0,
