+
+    // wood (vertical planks + grain)
+    function woodCanvas(base, dark, light) {
+      const c = canvas(256, 256), x = c.getContext('2d');
+      const hc = canvas(256, 256), hx = hc.getContext('2d');
+      for (let i = 0; i < 8; i++) {
+        const col = mix(base, i % 2 ? dark : light, 0.25 + rnd.next() * 0.2);
