+        hx.fillStyle = '#222'; hx.fillRect(i * 32, 0, 2, 256);
+        x.fillStyle = hex(shade(dark, 0.7)); x.fillRect(i * 32, 0, 2, 256);
+        for (let g = 0; g < 9; g++) {
+          x.strokeStyle = 'rgba(80,40,10,' + (0.15 + rnd.next() * 0.2).toFixed(2) + ')';
+          x.lineWidth = 1 + rnd.next();
