+    // knit bands for towers: stripes of gold / teal / rose / cream
+    const bandColors = [COL.gold, COL.teal, COL.rose, COL.cream, COL.purple, COL.gold];
+    M.knitBands = stitchMat(knit(256, 192, 16, 12, function (u, v) {
