+    [[96, 380, -0.8], [160, 330, 0.8], [100, 270, -0.6]].forEach(function (l) {
+      tx.save(); tx.translate(l[0], l[1]); tx.rotate(l[2]); tx.fillStyle = hex(COL.leaf);
