      update: function (r, dt) {
        targets(r);
        if (!ready) { pos.copy(wantPos); look.copy(wantLook); ready = true; }
        else if (dt > 0) { damp(pos, wantPos, CAM.posHalfLife, dt); damp(look, wantLook, CAM.lookHalfLife, dt); }
        this.apply();
