+    g.computeVertexNormals();
+    return g;
+  }
+
+  function tubeAlong(THREE, points, radius, segPerPoint) {
+    if (points.length < 2) return null;
+    const curve = new THREE.CatmullRomCurve3(points.map(function (p) { return new THREE.Vector3(p[0], p[1], p[2]); }));
